use crate::source::Source;
use anyhow::Context;
use escargot::{Cargo, CargoBuild, CommandMessages, format};
use smallvec::SmallVec;
use std::ops::{Deref, DerefMut};
use std::path::PathBuf;

/// Wasm blob is generated by a cargo invocation
#[derive(Debug)]
pub struct CargoSource(pub CargoBuild);

impl Deref for CargoSource {
    type Target = CargoBuild;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl DerefMut for CargoSource {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.0
    }
}

impl CargoSource {
    /// Create a new [`CargoSource`]
    ///
    /// `package`: The name of the crate to compile.
    pub fn new(package: &str) -> Self {
        Self::new_target(package, "wasm32-unknown-unknown")
    }

    /// Create a new [`CargoSource`]
    ///
    /// `package`: The name of the crate to compile.
    /// `target`: The wasm `--target` to compile to.
    pub fn new_target(package: &str, target: &str) -> Self {
        Self(
            Cargo::new()
                .build_with("rustc")
                .package(package)
                .target(target)
                .release()
                .args(["--crate-type", "cdylib"]),
        )
    }
}

impl Source for CargoSource {
    fn compile(self) -> anyhow::Result<Vec<u8>> {
        let output = self.0.exec()?;
        let artifact = extract_path(output, "cdylib", "cdylib")?;
        let wasm_bytes = std::fs::read(&artifact)
            .with_context(|| format!("Cargo artifact not found at path: {}", artifact.display()))?;
        Ok(wasm_bytes)
    }
}

fn extract_path(
    msgs: CommandMessages,
    desired_crate_type: &str,
    desired_kind: &str,
) -> anyhow::Result<PathBuf> {
    let artifacts = msgs
        .filter_map(move |m| {
            m.and_then(|m| {
                if let format::Message::CompilerArtifact(art) = m.decode()? {
                    log::trace!("artifact: {art:?}");
                    if !art.profile.test
                        && art.target.crate_types == [desired_crate_type]
                        && art.target.kind == [desired_kind]
                    {
                        return Ok(Some(
                            art.filenames
                                .first()
                                .expect("files must exist")
                                .to_path_buf(),
                        ));
                    }
                }
                Ok(None)
            })
            .transpose()
        })
        .collect::<Result<SmallVec<[PathBuf; 1]>, _>>()?;

    if artifacts.len() == 1 {
        Ok(artifacts.into_iter().next().unwrap())
    } else if artifacts.len() > 1 {
        Err(anyhow::format_err!(
            "Found more than one artifact: {artifacts:?}"
        ))
    } else {
        Err(anyhow::format_err!(
            "Found more than one artifact: {artifacts:?}"
        ))
    }
}
